import { getVercelEnv } from '@sentry/core';
import type { Logger } from './logger';
import type {
  InternalOptions as UserOptions,
  SetCommitsOptions,
  RewriteSourcesHook,
  ResolveSourceMapHook,
  IncludeEntry,
  ModuleMetadata,
  ModuleMetadataCallback,
} from './types';
import { canAutoDetectRepository, readCommitEnvVar, resolveReleaseName } from './utils';

export type NormalizedOptions = {
  org: string | undefined;
  project: string | string[] | undefined;
  authToken: string | undefined;
  url: string | undefined;
  headers: Record<string, string> | undefined;
  debug: boolean;
  silent: boolean;
  errorHandler: ((err: Error) => void) | undefined;
  telemetry: boolean;
  disable: boolean;
  sourcemaps:
    | {
        disable?: boolean | 'disable-upload';
        upload?: boolean;
        injectDebugIds?: boolean;
        delete?: boolean;
        assets?: string | string[];
        ignore?: string | string[];
        rewriteSources?: RewriteSourcesHook;
        resolveSourceMap?: ResolveSourceMapHook;
        filesToDeleteAfterUpload?: string | string[] | Promise<string | string[] | undefined>;
        deleteSourcemapsAfterUpload?: boolean | ((environment?: string) => boolean | undefined);
        sdkEnabledSourceMaps?: boolean | ((environment?: string) => boolean | undefined);
      }
    | undefined;
  release: {
    name: string | undefined;
    inject: boolean | 'html';
    create: boolean;
    finalize: boolean;
    vcsRemote: string;
    setCommits:
      | (SetCommitsOptions & {
          shouldNotThrowOnFailure?: boolean;
        })
      | false
      | undefined;
    dist?: string;
    deploy?:
      | {
          env: string;
          started?: number | string;
          finished?: number | string;
          time?: number;
          name?: string;
          url?: string;
        }
      | false;
    uploadLegacySourcemaps?: string | IncludeEntry | Array<string | IncludeEntry>;
  };
  bundleSizeOptimizations:
    | {
        excludeDebugStatements?: boolean;
        excludeTracing?: boolean;
        excludeChannelInjection?: boolean;
        excludeReplayCanvas?: boolean;
        excludeReplayShadowDom?: boolean;
        excludeReplayIframe?: boolean;
        excludeReplayWorker?: boolean;
      }
    | undefined;
  reactComponentAnnotation:
    | {
        enabled?: boolean;
        ignoredComponents?: string[];
        _experimentalInjectIntoHtml?: boolean;
      }
    | undefined;
  _metaOptions: {
    telemetry: {
      metaFramework: string | undefined;
      bundlerMajorVersion: string | undefined;
    };
  };
  applicationKey: string | undefined;
  moduleMetadata: ModuleMetadata | ModuleMetadataCallback | undefined;
  _experiments: {
    injectBuildInformation?: boolean;
  } & Record<string, unknown>;
};

export const SENTRY_SAAS_URL = 'https://sentry.io';

// oxlint-disable-next-line complexity
export function normalizeUserOptions(userOptions: UserOptions): NormalizedOptions {
  const options = {
    org: userOptions.org ?? process.env['SENTRY_ORG'],
    project:
      userOptions.project ??
      (process.env['SENTRY_PROJECT']?.includes(',')
        ? process.env['SENTRY_PROJECT'].split(',').map(p => p.trim())
        : process.env['SENTRY_PROJECT']),
    authToken: userOptions.authToken ?? process.env['SENTRY_AUTH_TOKEN'],
    // No sentry.io default: the CLI then uses the server an `sntrys_` org token was issued for, and
    // sentry.io otherwise. A default here would send self-hosted tokens to sentry.io.
    url: userOptions.url ?? process.env['SENTRY_URL'],
    headers: userOptions.headers,
    debug: userOptions.debug ?? false,
    silent: userOptions.silent ?? false,
    errorHandler: userOptions.errorHandler,
    telemetry: userOptions.telemetry ?? true,
    disable: userOptions.disable ?? false,
    sourcemaps: userOptions.sourcemaps,
    release: {
      ...userOptions.release,
      name: resolveReleaseName(userOptions.release?.name),
      inject: userOptions.release?.inject ?? true,
      create: userOptions.release?.create ?? true,
      finalize: userOptions.release?.finalize ?? true,
      vcsRemote: userOptions.release?.vcsRemote ?? process.env['SENTRY_VSC_REMOTE'] ?? 'origin',
      // oxlint-disable-next-line typescript/no-unnecessary-type-assertion -- rule false positive: the cast carries the internal `shouldNotThrowOnFailure` field; tsc errors without it
      setCommits: userOptions.release?.setCommits as
        | (SetCommitsOptions & { shouldNotThrowOnFailure?: boolean })
        | false
        | undefined,
    },
    bundleSizeOptimizations: userOptions.bundleSizeOptimizations,
    reactComponentAnnotation: userOptions.reactComponentAnnotation,
    _metaOptions: {
      telemetry: {
        metaFramework: userOptions._metaOptions?.telemetry?.metaFramework,
        bundlerMajorVersion: userOptions._metaOptions?.telemetry?.bundlerMajorVersion,
      },
    },
    applicationKey: userOptions.applicationKey,
    moduleMetadata: userOptions.moduleMetadata,
    _experiments: userOptions._experiments ?? {},
  };

  const vercelEnv = getVercelEnv();

  if (options.release.setCommits === undefined) {
    const vercelCommitSha = readCommitEnvVar('VERCEL_GIT_COMMIT_SHA');
    if (
      process.env['VERCEL'] &&
      vercelCommitSha &&
      process.env['VERCEL_GIT_REPO_SLUG'] &&
      process.env['VERCEL_GIT_REPO_OWNER'] &&
      // We only want to set commits for the production env because Sentry becomes extremely noisy (eg on slack) for
      // preview environments because the previous commit is always the "stem" commit of the preview/PR causing Sentry
      // to notify you for other people creating PRs.
      vercelEnv === 'production'
    ) {
      options.release.setCommits = {
        shouldNotThrowOnFailure: true,
        commit: vercelCommitSha,
        previousCommit: readCommitEnvVar('VERCEL_GIT_PREVIOUS_SHA'),
        repo: `${process.env['VERCEL_GIT_REPO_OWNER']}/${process.env['VERCEL_GIT_REPO_SLUG']}`,
        ignoreEmpty: true,
        ignoreMissing: true,
      };
    } else if (
      process.env['VERCEL'] &&
      vercelEnv !== 'production' &&
      !canAutoDetectRepository(options.release.vcsRemote)
    ) {
      // Vercel's own builders have no git remote and no other CI variables, so commit association can only fail there.
      // Builds that have either, such as `vercel build` in GitHub Actions, keep `auto: true` below.
      options.release.setCommits = false;
    } else {
      options.release.setCommits = {
        shouldNotThrowOnFailure: true,
        auto: true,
        ignoreEmpty: true,
        ignoreMissing: true,
      };
    }
  }

  if (options.release.deploy === undefined && process.env['VERCEL'] && vercelEnv) {
    options.release.deploy = {
      env: vercelEnv,
      url: process.env['VERCEL_URL'] ? `https://${process.env['VERCEL_URL']}` : undefined,
    };
  }

  return options;
}

/**
 * Validates a few combinations of options that are not checked by Sentry CLI.
 *
 * For all other options, we can rely on Sentry CLI to validate them. In fact,
 * we can't validate them in the plugin because Sentry CLI might pick up options from
 * its config file.
 *
 * @param options the internal options
 * @param logger the logger
 *
 * @returns `true` if the options are valid, `false` otherwise
 */
export function validateOptions(options: NormalizedOptions, logger: Logger): boolean {
  const setCommits = options.release?.setCommits;
  if (setCommits) {
    if (!setCommits.auto && !(setCommits.repo && setCommits.commit)) {
      logger.error(
        'The `setCommits` option was specified but is missing required properties.',
        'Please set either `auto` or both, `repo` and `commit`.',
      );
      return false;
    }
    if (setCommits.auto && setCommits.repo && setCommits) {
      logger.warn(
        'The `setCommits` options includes `auto` but also `repo` and `commit`.',
        'Ignoring `repo` and `commit`.',
        'Please only set either `auto` or both, `repo` and `commit`.',
      );
    }
  }

  const sourcemaps = options.sourcemaps;
  const usesFeatureOptions = sourcemaps?.upload !== undefined || sourcemaps?.injectDebugIds !== undefined;
  if (usesFeatureOptions && sourcemaps?.disable !== undefined) {
    logger.warn(
      '`sourcemaps.disable` is ignored because `sourcemaps.upload` or `sourcemaps.injectDebugIds` is set.',
      'Please remove `sourcemaps.disable`.',
    );
  }
  if (sourcemaps?.injectDebugIds === false && sourcemaps.upload === true) {
    logger.warn(
      '`sourcemaps.upload` is set, but `sourcemaps.injectDebugIds` is `false`.',
      'Source maps are not uploaded, because the upload matches files by debug ID.',
    );
  }
  if (sourcemaps?.delete !== undefined && sourcemaps.deleteSourcemapsAfterUpload !== undefined) {
    logger.warn(
      '`sourcemaps.deleteSourcemapsAfterUpload` is ignored because `sourcemaps.delete` is set.',
      'Please remove `sourcemaps.deleteSourcemapsAfterUpload`.',
    );
  }
  if (sourcemaps?.delete === false && sourcemaps.filesToDeleteAfterUpload !== undefined) {
    logger.warn(
      '`sourcemaps.filesToDeleteAfterUpload` still deletes the files it matches, although `sourcemaps.delete` is `false`.',
      'Remove `sourcemaps.filesToDeleteAfterUpload` to keep the source maps.',
    );
  }

  if (options.release?.deploy && typeof options.release.deploy === 'object' && !options.release.deploy.env) {
    logger.error(
      'The `deploy` option was specified but is missing the required `env` property.',
      'Please set the `env` property.',
    );
    return false;
  }

  if (options.project && Array.isArray(options.project)) {
    if (options.project.length === 0) {
      logger.error(
        'The `project` option was specified as an array but is empty.',
        'Please provide at least one project slug.',
      );
      return false;
    }
    // Check each project is a non-empty string
    const invalidProjects = options.project.filter(p => typeof p !== 'string' || p.trim() === '');
    if (invalidProjects.length > 0) {
      logger.error('The `project` option contains invalid project slugs.', 'All projects must be non-empty strings.');
      return false;
    }
  }

  return true;
}
